package com.discordchatboxbroadcaster.event;

import com.discordchatboxbroadcaster.DiscordChatboxBroadcasterConfig;
import com.discordchatboxbroadcaster.notifier.Notifier;
import com.discordchatboxbroadcaster.render.ChatSegment;
import com.discordchatboxbroadcaster.render.ChatSegment.Role;

import java.awt.image.BufferedImage;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class AchievementDiaryEventProcessor extends GameEventProcessor {

    private static final Pattern DIARY_PATTERN = Pattern.compile("Congratulations! You have completed all of the (\\w+) (?:tasks|achievements) in the (.+?) (?:area|set)\\.?", Pattern.CASE_INSENSITIVE);

    private final DiscordChatboxBroadcasterConfig pluginConfiguration;

    public AchievementDiaryEventProcessor(List<Notifier> registeredNotifiers, DiscordChatboxBroadcasterConfig pluginConfiguration) {
        super(registeredNotifiers);
        this.pluginConfiguration = pluginConfiguration;
    }

    @Override
    protected boolean isFeatureEnabled() {
        return pluginConfiguration.notifyAchievementDiary();
    }

    @Override
    protected void processSanitizedMessage(String sanitizedMessageContent, String activePlayerName, String activeClanName, BufferedImage playerIcon, int currentTick) {
        Matcher matcher = DIARY_PATTERN.matcher(sanitizedMessageContent);
        if (matcher.find()) {
            String tier = matcher.group(1);
            String area = matcher.group(2);

            // Capitalize tier
            if (tier.length() > 0) {
                tier = tier.substring(0, 1).toUpperCase() + tier.substring(1).toLowerCase();
            }

            executeNotificationSequence(activePlayerName, activeClanName, playerIcon, tier, area);
        }
    }

    private void executeNotificationSequence(String activePlayerName, String activeClanName, BufferedImage playerIcon, String tier, String area) {
        List<ChatSegment> notificationSegments = buildPlayerClanPrefixSegments(activePlayerName, activeClanName, playerIcon);
        notificationSegments.add(new ChatSegment("completed the ", Role.TEXT));
        notificationSegments.add(new ChatSegment(tier + " " + area, Role.HIGHLIGHT));
        notificationSegments.add(new ChatSegment(" diary.", Role.TEXT));

        dispatchNotificationSegments(notificationSegments);
    }
}

package com.discordchatboxbroadcaster.event;

import com.discordchatboxbroadcaster.DiscordChatboxBroadcasterConfig;
import com.discordchatboxbroadcaster.SharedEventState;
import com.discordchatboxbroadcaster.notifier.Notifier;
import com.discordchatboxbroadcaster.render.ChatSegment;
import com.discordchatboxbroadcaster.render.ChatSegment.Role;

import java.awt.image.BufferedImage;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class CollectionLogEventProcessor extends GameEventProcessor {

    private static final Pattern COLLECTION_LOG_DETECTION_PATTERN = Pattern.compile("New item added to your collection log: (.*)");

    private final DiscordChatboxBroadcasterConfig pluginConfiguration;
    private final SharedEventState sharedEventState;

    public CollectionLogEventProcessor(List<Notifier> registeredNotifiers, DiscordChatboxBroadcasterConfig pluginConfiguration, SharedEventState sharedEventState) {
        super(registeredNotifiers);
        this.pluginConfiguration = pluginConfiguration;
        this.sharedEventState = sharedEventState;
    }

    @Override
    protected boolean isFeatureEnabled() {
        return pluginConfiguration.notifyCollectionLog();
    }

    @Override
    protected void processSanitizedMessage(String sanitizedMessageContent, String activePlayerName, String activeClanName, BufferedImage playerIcon, int currentTick) {
        if (currentTick != -1 && sharedEventState.isWithinPetDropWindow(currentTick)) {
            return;
        }

        Matcher patternMatcher = COLLECTION_LOG_DETECTION_PATTERN.matcher(sanitizedMessageContent);

        if (patternMatcher.find()) {
            if (currentTick != -1) {
                sharedEventState.registerCollectionLogDrop(currentTick);
            }

            executeNotificationSequence(activePlayerName, activeClanName, playerIcon, patternMatcher.group(1));
        }
    }

    private void executeNotificationSequence(String activePlayerName, String activeClanName, BufferedImage playerIcon, String itemName) {
        List<ChatSegment> notificationSegments = buildPlayerClanPrefixSegments(activePlayerName, activeClanName, playerIcon);
        notificationSegments.add(new ChatSegment("received a new collection log item: ", Role.TEXT));
        notificationSegments.add(new ChatSegment(itemName, Role.HIGHLIGHT));

        dispatchNotificationSegments(notificationSegments);
    }
}

package com.discordchatboxbroadcaster.event;

import com.discordchatboxbroadcaster.DiscordChatboxBroadcasterConfig;
import com.discordchatboxbroadcaster.config.CombatAchievementTier;
import com.discordchatboxbroadcaster.notifier.Notifier;
import com.discordchatboxbroadcaster.render.ChatSegment;
import com.discordchatboxbroadcaster.render.ChatSegment.Role;

import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class CombatAchievementEventProcessor extends GameEventProcessor {

    private static final Pattern COMBAT_ACHIEVEMENT_DETECTION_PATTERN = Pattern.compile("(?:CA_ID:\\d+\\|)?Congratulations, you've completed an? (\\w+) combat task: (.*)");
    private static final Pattern TIER_COMPLETION_PATTERN = Pattern.compile("You've completed enough Combat Achievement tasks to unlock the (\\w+) Tier rewards!.*", Pattern.CASE_INSENSITIVE);

    private final DiscordChatboxBroadcasterConfig pluginConfiguration;

    public CombatAchievementEventProcessor(List<Notifier> registeredNotifiers, DiscordChatboxBroadcasterConfig pluginConfiguration) {
        super(registeredNotifiers);
        this.pluginConfiguration = pluginConfiguration;
    }

    @Override
    protected boolean isFeatureEnabled() {
        return pluginConfiguration.notifyCombatAchievement();
    }

    @Override
    protected void processSanitizedMessage(String sanitizedMessageContent, String activePlayerName, String activeClanName, BufferedImage playerIcon, int currentTick) {
        Matcher patternMatcher = COMBAT_ACHIEVEMENT_DETECTION_PATTERN.matcher(sanitizedMessageContent);

        if (patternMatcher.find()) {
            String capturedTier = patternMatcher.group(1);
            CombatAchievementTier taskTier = CombatAchievementTier.fromName(capturedTier);
            if (taskTier != null) {
                CombatAchievementTier minTier = pluginConfiguration.combatAchievementMinTier();
                if (minTier == null) {
                    minTier = CombatAchievementTier.EASY;
                }
                if (taskTier.ordinal() < minTier.ordinal()) {
                    return;
                }
            }

            String taskName = patternMatcher.group(2);
            if (taskName.endsWith(".")) {
                taskName = taskName.substring(0, taskName.length() - 1);
            }
            executeNotificationSequence(activePlayerName, activeClanName, playerIcon, capturedTier.toLowerCase(), taskName);
            return;
        }

        Matcher tierMatcher = TIER_COMPLETION_PATTERN.matcher(sanitizedMessageContent);
        if (tierMatcher.find()) {
            if (!pluginConfiguration.notifyCombatAchievementTierCompletion()) {
                return;
            }
            String tier = tierMatcher.group(1);
            executeTierNotificationSequence(activePlayerName, activeClanName, playerIcon, tier);
        }
    }

    private void executeNotificationSequence(String activePlayerName, String activeClanName, BufferedImage playerIcon, String tier, String taskName) {
        List<ChatSegment> notificationSegments = buildPlayerClanPrefixSegments(activePlayerName, activeClanName, playerIcon);
        notificationSegments.add(new ChatSegment("has completed a ", Role.TEXT));
        notificationSegments.add(new ChatSegment(tier, Role.HIGHLIGHT));
        notificationSegments.add(new ChatSegment(" combat task: ", Role.TEXT));
        notificationSegments.add(new ChatSegment(taskName + ".", Role.HIGHLIGHT));

        dispatchNotificationSegments(notificationSegments);
    }

    private void executeTierNotificationSequence(String activePlayerName, String activeClanName, BufferedImage playerIcon, String tier) {
        List<ChatSegment> segments = new ArrayList<>(buildPlayerClanPrefixSegments(activePlayerName, activeClanName, playerIcon));
        segments.add(new ChatSegment("has completed the ", Role.TEXT));
        segments.add(new ChatSegment(tier + " Tier", Role.HIGHLIGHT));
        segments.add(new ChatSegment(" of Combat Achievements!", Role.TEXT));

        dispatchNotificationSegments(segments);
    }
}

package com.discordchatboxbroadcaster.event;

import com.discordchatboxbroadcaster.DiscordChatboxBroadcasterConfig;
import com.discordchatboxbroadcaster.notifier.Notifier;
import com.discordchatboxbroadcaster.render.ChatSegment;
import com.discordchatboxbroadcaster.render.ChatSegment.Role;
import net.runelite.api.events.ActorDeath;

import java.awt.image.BufferedImage;
import java.util.List;

public class DeathEventProcessor extends GameEventProcessor {

    private final DiscordChatboxBroadcasterConfig pluginConfiguration;

    public DeathEventProcessor(List<Notifier> registeredNotifiers, DiscordChatboxBroadcasterConfig pluginConfiguration) {
        super(registeredNotifiers);
        this.pluginConfiguration = pluginConfiguration;
    }

    @Override
    protected boolean isFeatureEnabled() {
        return pluginConfiguration.notifyDeath();
    }

    @Override
    protected void processSanitizedMessage(String sanitizedMessageContent, String activePlayerName, String activeClanName, BufferedImage playerIcon, int currentTick) {
    }

    @Override
    public void evaluateActorDeath(ActorDeath incomingDeathEvent, String activePlayerName, String activeClanName, BufferedImage playerIcon, int currentTick) {
        if (!isFeatureEnabled() || !canProcessEvent(currentTick)) {
            return;
        }

        if (incomingDeathEvent.getActor() == null || incomingDeathEvent.getActor().getName() == null || !incomingDeathEvent.getActor().getName().equals(activePlayerName)) {
            return;
        }

        executeNotificationSequence(activePlayerName, activeClanName, playerIcon);
    }

    private void executeNotificationSequence(String activePlayerName, String activeClanName, BufferedImage playerIcon) {
        List<ChatSegment> notificationSegments = buildPlayerClanPrefixSegments(activePlayerName, activeClanName, playerIcon);
        notificationSegments.add(new ChatSegment("has died.", Role.TEXT));

        dispatchNotificationSegments(notificationSegments);
    }
}

package com.discordchatboxbroadcaster.event;

import com.discordchatboxbroadcaster.notifier.Notifier;
import com.discordchatboxbroadcaster.render.ChatSegment;
import com.discordchatboxbroadcaster.render.ChatSegment.Role;
import net.runelite.api.ChatMessageType;
import net.runelite.api.GameState;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.StatChanged;

import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;

public abstract class GameEventProcessor {

    private final List<Notifier> registeredNotifiers;

    public GameEventProcessor(List<Notifier> registeredNotifiers) {
        this.registeredNotifiers = registeredNotifiers;
    }

    protected abstract boolean isFeatureEnabled();

    protected abstract void processSanitizedMessage(String sanitizedMessageContent, String activePlayerName, String activeClanName, BufferedImage playerIcon, int currentTick);

    protected boolean canProcessEvent(int currentTick) {
        return true;
    }

    public void evaluateIncomingEvent(ChatMessage incomingChatMessage, String activePlayerName, String activeClanName, BufferedImage playerIcon, int currentTick) {
        if (!isFeatureEnabled() || !canProcessEvent(currentTick)) {
            return;
        }

        ChatMessageType incomingMessageType = incomingChatMessage.getType();
        String typeName = incomingMessageType.name();

        boolean isGameMessage = incomingMessageType == ChatMessageType.GAMEMESSAGE
                || incomingMessageType == ChatMessageType.SPAM
                || incomingMessageType == ChatMessageType.MESBOX
                || incomingMessageType == ChatMessageType.DIALOG
                || incomingMessageType == ChatMessageType.FRIENDSCHATNOTIFICATION;
        boolean isLevelUp = typeName.contains("LEVELUP") || typeName.contains("LEVEL_UP");

        if (!isGameMessage && !isLevelUp) {
            return;
        }

        String senderName = incomingChatMessage.getName();
        if (senderName != null && !senderName.trim().isEmpty()) {
            return;
        }

        String sanitizedMessageContent = incomingChatMessage.getMessage()
                .replaceAll("(?i)<br\\s*/?>", " ")
                .replaceAll("<[^>]+>", "")
                .replaceAll("@[a-zA-Z0-9_]+@", "")
                .replaceAll("\\s+", " ")
                .trim();
        processSanitizedMessage(sanitizedMessageContent, activePlayerName, activeClanName, playerIcon, currentTick);
    }

    public void evaluateActorDeath(ActorDeath incomingDeathEvent, String activePlayerName, String activeClanName, BufferedImage playerIcon, int currentTick) {
    }


    public void evaluateGameStateChanged(GameState newGameState) {
    }

    public void evaluateStatChanged(StatChanged incomingStatEvent, String activePlayerName, String activeClanName, BufferedImage playerIcon, int currentTick) {
    }

    protected List<ChatSegment> buildPlayerClanPrefixSegments(String activePlayerName, String activeClanName, BufferedImage playerIcon) {
        List<ChatSegment> prefixSegments = new ArrayList<>();

        if (activeClanName != null && !activeClanName.isEmpty()) {
            prefixSegments.add(new ChatSegment("[" + activeClanName + "] ", Role.CLAN));
        }

        if (playerIcon != null) {
            prefixSegments.add(new ChatSegment(playerIcon));
        }

        prefixSegments.add(new ChatSegment(activePlayerName + " ", Role.TEXT));

        return prefixSegments;
    }

    protected void dispatchNotificationSegments(List<ChatSegment> generatedSegments) {
        for (Notifier currentNotifier : registeredNotifiers) {
            currentNotifier.dispatchNotification(generatedSegments);
        }
    }

    public void evaluateGameTick(int currentTick) {
    }
}

package com.discordchatboxbroadcaster.event;

import com.discordchatboxbroadcaster.DiscordChatboxBroadcasterConfig;
import com.discordchatboxbroadcaster.notifier.Notifier;
import com.discordchatboxbroadcaster.render.ChatSegment;
import com.discordchatboxbroadcaster.render.ChatSegment.Role;

import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class KillEventProcessor extends GameEventProcessor {

    private static final Pattern KILL_DETECTION_PATTERN = Pattern.compile("You have defeated (.*?)(?: and received (.*) coins)?\\.");

    private final DiscordChatboxBroadcasterConfig pluginConfiguration;
    private final Map<String, Integer> recentPlayerDeaths = new HashMap<>();

    public KillEventProcessor(List<Notifier> registeredNotifiers, DiscordChatboxBroadcasterConfig pluginConfiguration) {
        super(registeredNotifiers);
        this.pluginConfiguration = pluginConfiguration;
    }

    @Override
    protected boolean isFeatureEnabled() {
        return pluginConfiguration.notifyKill();
    }

    @Override
    protected void processSanitizedMessage(String sanitizedMessageContent, String activePlayerName, String activeClanName, BufferedImage playerIcon, int currentTick) {
        Matcher patternMatcher = KILL_DETECTION_PATTERN.matcher(sanitizedMessageContent);

        if (patternMatcher.find()) {
            String defeatedTarget = patternMatcher.group(1).replace('\u00A0', ' ');
            String coinsReceived = patternMatcher.group(2);

            Integer deathTick = recentPlayerDeaths.get(defeatedTarget);

            // A 10-tick window is appropriate because the ActorDeath event triggers when
            // HP reaches 0, but the chat message may not appear until the death animation 
            // completes (which is around 5-8 ticks for players).
            //
            // Edge Case Note: If a player defeats an NPC (e.g., a boss) that triggers a 
            // "You have defeated X." message, AND a player with the exact same name as 
            // the NPC died in the vicinity within the last 10 ticks, it will falsely 
            // broadcast as a PvP kill. This is extremely unlikely and accepted.
            if (deathTick == null || Math.abs(currentTick - deathTick) > 10) {
                return; // Target was not a player that died recently
            }

            executeNotificationSequence(activePlayerName, activeClanName, playerIcon, defeatedTarget, coinsReceived);
        }
    }

    @Override
    public void evaluateActorDeath(net.runelite.api.events.ActorDeath incomingDeathEvent, String activePlayerName, String activeClanName, BufferedImage playerIcon, int currentTick) {
        if (incomingDeathEvent.getActor() instanceof net.runelite.api.Player) {
            net.runelite.api.Player deadPlayer = (net.runelite.api.Player) incomingDeathEvent.getActor();
            if (deadPlayer.getName() != null) {
                String cleanName = deadPlayer.getName().replace('\u00A0', ' ');
                recentPlayerDeaths.put(cleanName, currentTick);
            }
        }
    }

    @Override
    public void evaluateGameTick(int currentTick) {
        recentPlayerDeaths.entrySet().removeIf(entry -> Math.abs(currentTick - entry.getValue()) > 20);
    }

    private void executeNotificationSequence(String activePlayerName, String activeClanName, BufferedImage playerIcon, String defeatedTarget, String coinsReceived) {
        List<ChatSegment> notificationSegments = buildPlayerClanPrefixSegments(activePlayerName, activeClanName, playerIcon);
        notificationSegments.add(new ChatSegment("has defeated ", Role.TEXT));
        notificationSegments.add(new ChatSegment(defeatedTarget, Role.HIGHLIGHT));

        if (coinsReceived != null) {
            notificationSegments.add(new ChatSegment(" and received ", Role.TEXT));
            notificationSegments.add(new ChatSegment(coinsReceived + " coins", Role.HIGHLIGHT));
        }

        notificationSegments.add(new ChatSegment("!", Role.TEXT));

        dispatchNotificationSegments(notificationSegments);
    }
}

package com.discordchatboxbroadcaster.event;

import com.discordchatboxbroadcaster.DiscordChatboxBroadcasterConfig;
import com.discordchatboxbroadcaster.notifier.Notifier;
import com.discordchatboxbroadcaster.render.ChatSegment;
import com.discordchatboxbroadcaster.render.ChatSegment.Role;

import java.awt.image.BufferedImage;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class LevelUpEventProcessor extends GameEventProcessor {

    private static final Pattern MAX_LEVEL_PATTERN = Pattern.compile("Congratulations, you(?:'ve)? reached the highest possible (.*?) level of 99\\.");
    private static final Pattern STANDARD_LEVEL_NAME_PATTERN = Pattern.compile("Congratulations, you(?:'ve)? just advanced (?:a|an|your) (.*?) level\\.");
    private static final Pattern STANDARD_LEVEL_NUMBER_PATTERN = Pattern.compile("You are now level (\\d+)\\.");

    private final DiscordChatboxBroadcasterConfig pluginConfiguration;

    public LevelUpEventProcessor(List<Notifier> registeredNotifiers, DiscordChatboxBroadcasterConfig pluginConfiguration) {
        super(registeredNotifiers);
        this.pluginConfiguration = pluginConfiguration;
    }

    @Override
    protected boolean isFeatureEnabled() {
        return pluginConfiguration.notifyLevelUp();
    }

    @Override
    protected void processSanitizedMessage(String sanitizedMessageContent, String activePlayerName, String activeClanName, BufferedImage playerIcon, int currentTick) {
        Matcher maxLevelMatcher = MAX_LEVEL_PATTERN.matcher(sanitizedMessageContent);

        if (maxLevelMatcher.find()) {
            if (!shouldBroadcastLevel(99)) {
                return;
            }
            executeNotificationSequence(activePlayerName, activeClanName, playerIcon, maxLevelMatcher.group(1), "99");
            return;
        }

        Matcher skillNameMatcher = STANDARD_LEVEL_NAME_PATTERN.matcher(sanitizedMessageContent);

        if (skillNameMatcher.find()) {
            String skillName = skillNameMatcher.group(1);
            String skillLevel = null;

            Matcher skillLevelMatcher = STANDARD_LEVEL_NUMBER_PATTERN.matcher(sanitizedMessageContent);

            if (skillLevelMatcher.find()) {
                skillLevel = skillLevelMatcher.group(1);
            }

            Integer parsedLevel = null;
            if (skillLevel != null) {
                try {
                    parsedLevel = Integer.parseInt(skillLevel);
                } catch (NumberFormatException ignored) {
                }
            }

            if (!shouldBroadcastLevel(parsedLevel)) {
                return;
            }

            executeNotificationSequence(activePlayerName, activeClanName, playerIcon, skillName, skillLevel);
        }
    }

    private boolean shouldBroadcastLevel(Integer level) {
        if (level == null) {
            return true;
        }
        int minLevel = Math.max(1, pluginConfiguration.levelUpMinLevel());
        int interval = Math.max(1, pluginConfiguration.levelUpInterval());
        return level >= minLevel && (level % interval == 0 || level == 99);
    }

    private void executeNotificationSequence(String activePlayerName, String activeClanName, BufferedImage playerIcon, String skillName, String skillLevel) {
        List<ChatSegment> notificationSegments = buildPlayerClanPrefixSegments(activePlayerName, activeClanName, playerIcon);

        if (skillLevel != null) {
            notificationSegments.add(new ChatSegment("has reached ", Role.TEXT));
            notificationSegments.add(new ChatSegment(skillName + " level " + skillLevel, Role.HIGHLIGHT));
            notificationSegments.add(new ChatSegment(".", Role.TEXT));
        } else {
            notificationSegments.add(new ChatSegment("advanced a level: ", Role.TEXT));
            notificationSegments.add(new ChatSegment(skillName, Role.HIGHLIGHT));
        }

        dispatchNotificationSegments(notificationSegments);
    }
}

package com.discordchatboxbroadcaster.event;

import com.discordchatboxbroadcaster.DiscordChatboxBroadcasterConfig;
import com.discordchatboxbroadcaster.notifier.Notifier;
import com.discordchatboxbroadcaster.render.ChatSegment;
import com.discordchatboxbroadcaster.render.ChatSegment.Role;
import net.runelite.api.GameState;

import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class NewRecordEventProcessor extends GameEventProcessor {

    private static final Pattern RECORD_DETECTION_PATTERN = Pattern.compile(
        "(?i)^(?:(?<prefix>.+?) )??(?<detail>(?:(?:Fight |Lap |Challenge |Corrupted challenge )?duration:|Subdued in|(?<!challenge )(?:Total )?completion time:) [0-9:]+(?:\\.\\d+)?) \\(new personal best\\)"
    );
    private static final Pattern COX_RECORD_PATTERN = Pattern.compile(
        "(?i)Congratulations - your raid is complete!.*?(?<detail>Duration: [0-9:]+(?:\\.\\d+)?) \\(new personal best\\)"
    );
    private static final Pattern RAID_COMPLETION_PREFIX_PATTERN = Pattern.compile(
        "(?i)^(?<prefix>.+?) (?<!challenge )(?:Total )?completion time: [0-9:]+"
    );
    private static final Pattern KILLCOUNT_PATTERN = Pattern.compile(
        "(?i)Your (?:completion count for |subdued |completed )?(.+?) (?:(?:kill|chest|harvest|lap|completion|success|opened|Total Ticket) )?(?:count )?is: ?[0-9,]+"
    );

    private final DiscordChatboxBroadcasterConfig pluginConfiguration;

    private String cachedBossName = null;
    private int bossNameTick = -1;
    private String pendingRecordDetails = null;
    private List<ChatSegment> pendingPrefixSegments = null;
    private int pendingRecordTick = -1;

    public NewRecordEventProcessor(List<Notifier> registeredNotifiers, DiscordChatboxBroadcasterConfig pluginConfiguration) {
        super(registeredNotifiers);
        this.pluginConfiguration = pluginConfiguration;
    }

    @Override
    protected boolean isFeatureEnabled() {
        return pluginConfiguration.notifyNewRecord();
    }

    @Override
    public void evaluateGameStateChanged(GameState newGameState) {
        if (newGameState == GameState.LOGIN_SCREEN || newGameState == GameState.HOPPING) {
            cachedBossName = null;
            bossNameTick = -1;
            pendingRecordDetails = null;
            pendingPrefixSegments = null;
            pendingRecordTick = -1;
        }
    }

    @Override
    public void evaluateGameTick(int currentTick) {
        if (pendingRecordDetails != null) {
            if (currentTick > pendingRecordTick) {
                String resolvedBoss = (cachedBossName != null && Math.abs(currentTick - bossNameTick) <= 2) ? cachedBossName : null;
                if (pluginConfiguration.notifyNewRecord() && pendingPrefixSegments != null) {
                    sendRecordNotification(pendingPrefixSegments, resolvedBoss, pendingRecordDetails);
                }
                pendingRecordDetails = null;
                pendingPrefixSegments = null;
                pendingRecordTick = -1;
            }
        }

        if (cachedBossName != null && Math.abs(currentTick - bossNameTick) > 2) {
            cachedBossName = null;
            bossNameTick = -1;
        }
    }

    @Override
    protected void processSanitizedMessage(String sanitizedMessageContent, String activePlayerName, String activeClanName, BufferedImage playerIcon, int currentTick) {
        Matcher kcMatcher = KILLCOUNT_PATTERN.matcher(sanitizedMessageContent);
        if (kcMatcher.find()) {
            cachedBossName = kcMatcher.group(1).trim();
            bossNameTick = currentTick;
            if (pendingRecordDetails != null) {
                if (pluginConfiguration.notifyNewRecord() && pendingPrefixSegments != null) {
                    sendRecordNotification(pendingPrefixSegments, cachedBossName, pendingRecordDetails);
                }
                pendingRecordDetails = null;
                pendingPrefixSegments = null;
                pendingRecordTick = -1;
            }
            return;
        }

        Matcher coxMatcher = COX_RECORD_PATTERN.matcher(sanitizedMessageContent);
        if (coxMatcher.find()) {
            if (pluginConfiguration.notifyNewRecord()) {
                sendRecordNotification(buildPlayerClanPrefixSegments(activePlayerName, activeClanName, playerIcon), "Chambers of Xeric", coxMatcher.group("detail"));
            }
            return;
        }

        Matcher recordMatcher = RECORD_DETECTION_PATTERN.matcher(sanitizedMessageContent);
        if (recordMatcher.find()) {
            String inlinePrefix = recordMatcher.group("prefix");
            String recordDetails = recordMatcher.group("detail");

            if (inlinePrefix != null && !inlinePrefix.trim().isEmpty()) {
                cachedBossName = inlinePrefix.trim().replaceAll(":$", "").trim();
                bossNameTick = currentTick;
            }

            if (pendingRecordDetails != null) {
                if (pluginConfiguration.notifyNewRecord() && pendingPrefixSegments != null) {
                    sendRecordNotification(pendingPrefixSegments, cachedBossName, pendingRecordDetails);
                }
                pendingRecordDetails = null;
                pendingPrefixSegments = null;
                pendingRecordTick = -1;
            }

            if (!pluginConfiguration.notifyNewRecord()) {
                return;
            }

            String resolvedBoss = (cachedBossName != null && Math.abs(currentTick - bossNameTick) <= 2) ? cachedBossName : null;
            if (resolvedBoss != null) {
                sendRecordNotification(buildPlayerClanPrefixSegments(activePlayerName, activeClanName, playerIcon), resolvedBoss, recordDetails);
            } else {
                pendingRecordDetails = recordDetails;
                pendingPrefixSegments = buildPlayerClanPrefixSegments(activePlayerName, activeClanName, playerIcon);
                pendingRecordTick = currentTick;
            }
            return;
        }

        Matcher raidPrefixMatcher = RAID_COMPLETION_PREFIX_PATTERN.matcher(sanitizedMessageContent);
        if (raidPrefixMatcher.find()) {
            String prefix = raidPrefixMatcher.group("prefix").trim().replaceAll(":$", "").trim();
            if (!prefix.equalsIgnoreCase("Challenge") && !prefix.equalsIgnoreCase("Total")) {
                cachedBossName = prefix;
                bossNameTick = currentTick;
                if (pendingRecordDetails != null) {
                    if (pluginConfiguration.notifyNewRecord() && pendingPrefixSegments != null) {
                        sendRecordNotification(pendingPrefixSegments, cachedBossName, pendingRecordDetails);
                    }
                    pendingRecordDetails = null;
                    pendingPrefixSegments = null;
                    pendingRecordTick = -1;
                }
            }
        }
    }

    private void sendRecordNotification(List<ChatSegment> prefixSegments, String bossName, String recordDetails) {
        List<ChatSegment> segments = new ArrayList<>(prefixSegments);
        if (bossName != null && !bossName.isEmpty()) {
            segments.add(new ChatSegment("achieved a new ", Role.TEXT));
            segments.add(new ChatSegment(bossName, Role.HIGHLIGHT));
            segments.add(new ChatSegment(" record: ", Role.TEXT));
        } else {
            segments.add(new ChatSegment("achieved a new record: ", Role.TEXT));
        }
        segments.add(new ChatSegment(recordDetails, Role.HIGHLIGHT));
        dispatchNotificationSegments(segments);
    }
}

package com.discordchatboxbroadcaster.event;

import com.discordchatboxbroadcaster.DiscordChatboxBroadcasterConfig;
import com.discordchatboxbroadcaster.SharedEventState;
import com.discordchatboxbroadcaster.notifier.Notifier;
import com.discordchatboxbroadcaster.render.ChatSegment;
import com.discordchatboxbroadcaster.render.ChatSegment.Role;

import java.awt.image.BufferedImage;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class PetEventProcessor extends GameEventProcessor {

    private static final Pattern PET_DETECTION_PATTERN = Pattern.compile("(You have a funny feeling[^:]+|You feel something weird sneaking into your backpack[^:]+)(?:: (.*?)(?: at (.*))?)?");
    private static final Pattern UNTRADEABLE_DROP_PATTERN = Pattern.compile("Untradeable drop: (?:\\d+ x )?(.*)");

    private final DiscordChatboxBroadcasterConfig pluginConfiguration;
    private final SharedEventState sharedEventState;

    private int cachedFunnyFeelingTick = -1;
    private String cachedFunnyFeelingMessage = null;
    private String cachedPlayerName = null;
    private String cachedClanName = null;
    private BufferedImage cachedPlayerIcon = null;

    private int cachedUntradeableDropTick = -1;
    private String cachedUntradeableDropName = null;

    public PetEventProcessor(List<Notifier> registeredNotifiers, DiscordChatboxBroadcasterConfig pluginConfiguration, SharedEventState sharedEventState) {
        super(registeredNotifiers);
        this.pluginConfiguration = pluginConfiguration;
        this.sharedEventState = sharedEventState;
    }

    @Override
    protected boolean isFeatureEnabled() {
        return pluginConfiguration.notifyPet();
    }

    @Override
    protected void processSanitizedMessage(String sanitizedMessageContent, String activePlayerName, String activeClanName, BufferedImage playerIcon, int currentTick) {
        Matcher patternMatcher = PET_DETECTION_PATTERN.matcher(sanitizedMessageContent);

        if (patternMatcher.find()) {
            if (currentTick != -1) {
                sharedEventState.registerPetDrop(currentTick);
            }

            String baseMessage = patternMatcher.group(1);
            String petName = patternMatcher.group(2);
            String kcOrXp = patternMatcher.group(3);

            if (baseMessage != null) {
                baseMessage = baseMessage.replaceAll("\\.+$", "").trim();
            }
            if (petName != null) {
                petName = petName.replaceAll("\\.+$", "").trim();
            }
            if (kcOrXp != null) {
                kcOrXp = kcOrXp.replaceAll("\\.+$", "").trim();
            }

            if (petName != null && !petName.isEmpty()) {
                executeNotificationSequence(activePlayerName, activeClanName, playerIcon, baseMessage, petName, kcOrXp);
            } else {
                cachedFunnyFeelingTick = currentTick;
                cachedFunnyFeelingMessage = baseMessage;
                cachedPlayerName = activePlayerName;
                cachedClanName = activeClanName;
                cachedPlayerIcon = playerIcon;

                checkAndFireCachedEvent();
            }
            return;
        }

        Matcher untradeableMatcher = UNTRADEABLE_DROP_PATTERN.matcher(sanitizedMessageContent);
        if (untradeableMatcher.find()) {
            String petName = untradeableMatcher.group(1);
            if (petName != null) {
                petName = petName.replaceAll("\\.+$", "").trim();
            }
            cachedUntradeableDropTick = currentTick;
            cachedUntradeableDropName = petName;

            checkAndFireCachedEvent();
        }
    }

    private void checkAndFireCachedEvent() {
        if (cachedFunnyFeelingMessage != null && cachedUntradeableDropName != null) {
            if (Math.abs(cachedFunnyFeelingTick - cachedUntradeableDropTick) <= 1 || cachedFunnyFeelingTick == -1 || cachedUntradeableDropTick == -1) {
                executeNotificationSequence(cachedPlayerName, cachedClanName, cachedPlayerIcon, cachedFunnyFeelingMessage, cachedUntradeableDropName, null);
                clearFunnyFeelingCache();
                clearUntradeableDropCache();
            }
        }
    }

    private void clearFunnyFeelingCache() {
        cachedFunnyFeelingTick = -1;
        cachedFunnyFeelingMessage = null;
        cachedPlayerName = null;
        cachedClanName = null;
        cachedPlayerIcon = null;
    }

    private void clearUntradeableDropCache() {
        cachedUntradeableDropTick = -1;
        cachedUntradeableDropName = null;
    }

    @Override
    public void evaluateGameTick(int currentTick) {
        if (cachedFunnyFeelingMessage != null && currentTick > cachedFunnyFeelingTick + 1 && cachedFunnyFeelingTick != -1) {
            executeNotificationSequence(cachedPlayerName, cachedClanName, cachedPlayerIcon, cachedFunnyFeelingMessage, null, null);
            clearFunnyFeelingCache();
        }
        if (cachedUntradeableDropName != null && currentTick > cachedUntradeableDropTick + 1 && cachedUntradeableDropTick != -1) {
            clearUntradeableDropCache();
        }
    }

    private void executeNotificationSequence(String activePlayerName, String activeClanName, BufferedImage playerIcon, String baseMessage, String petName, String kcOrXp) {
        String formattedPetMessage = baseMessage
                .replace("You have a funny feeling like you're", "has a funny feeling like they're")
                .replace("You feel something weird sneaking into your", "feels something weird sneaking into their")
                .replace("You have a funny feeling like you would have been", "has a funny feeling like they would have been");

        List<ChatSegment> notificationSegments = buildPlayerClanPrefixSegments(activePlayerName, activeClanName, playerIcon);

        if (petName != null && !petName.isEmpty()) {
            notificationSegments.add(new ChatSegment(formattedPetMessage + ": ", Role.TEXT));
            notificationSegments.add(new ChatSegment(petName, Role.HIGHLIGHT));

            if (kcOrXp != null && !kcOrXp.isEmpty()) {
                notificationSegments.add(new ChatSegment(" at " + kcOrXp + ".", Role.TEXT));
            } else {
                notificationSegments.add(new ChatSegment(".", Role.TEXT));
            }
        } else {
            notificationSegments.add(new ChatSegment(formattedPetMessage + ".", Role.TEXT));
        }

        dispatchNotificationSegments(notificationSegments);
    }
}

