package com.discordchatboxbroadcaster.event;

import com.discordchatboxbroadcaster.DiscordChatboxBroadcasterConfig;
import com.discordchatboxbroadcaster.SharedEventState;
import com.discordchatboxbroadcaster.notifier.Notifier;
import com.discordchatboxbroadcaster.render.ChatSegment;
import com.discordchatboxbroadcaster.render.ChatSegment.Role;

import java.awt.image.BufferedImage;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ValuableDropEventProcessor extends GameEventProcessor {

    private static final Pattern VALUABLE_DROP_DETECTION_PATTERN = Pattern.compile("Valuable drop: (?:\\d+ x )?(.*)");
    private static final Pattern VALUE_PATTERN = Pattern.compile("\\((\\d[\\d,]*) coins\\)", Pattern.CASE_INSENSITIVE);

    private final DiscordChatboxBroadcasterConfig pluginConfiguration;
    private final SharedEventState sharedEventState;

    public ValuableDropEventProcessor(List<Notifier> registeredNotifiers, DiscordChatboxBroadcasterConfig pluginConfiguration, SharedEventState sharedEventState) {
        super(registeredNotifiers);
        this.pluginConfiguration = pluginConfiguration;
        this.sharedEventState = sharedEventState;
    }

    @Override
    protected boolean isFeatureEnabled() {
        return pluginConfiguration.notifyValuableDrop();
    }

    @Override
    protected void processSanitizedMessage(String sanitizedMessageContent, String activePlayerName, String activeClanName, BufferedImage playerIcon, int currentTick) {
        if (currentTick != -1 && sharedEventState.isWithinCollectionLogWindow(currentTick)) {
            return;
        }

        Matcher patternMatcher = VALUABLE_DROP_DETECTION_PATTERN.matcher(sanitizedMessageContent);

        if (patternMatcher.find()) {
            int minValue = pluginConfiguration.valuableDropMinValue();
            if (minValue > 0) {
                Matcher valueMatcher = VALUE_PATTERN.matcher(sanitizedMessageContent);
                if (valueMatcher.find()) {
                    try {
                        long value = Long.parseLong(valueMatcher.group(1).replace(",", ""));
                        if (value < minValue) {
                            return;
                        }
                    } catch (NumberFormatException ignored) {
                    }
                }
            }
            executeNotificationSequence(activePlayerName, activeClanName, playerIcon, patternMatcher.group(1));
        }
    }

    private void executeNotificationSequence(String activePlayerName, String activeClanName, BufferedImage playerIcon, String dropDetails) {
        List<ChatSegment> notificationSegments = buildPlayerClanPrefixSegments(activePlayerName, activeClanName, playerIcon);
        notificationSegments.add(new ChatSegment("received a drop: ", Role.TEXT));
        notificationSegments.add(new ChatSegment(dropDetails, Role.HIGHLIGHT));

        dispatchNotificationSegments(notificationSegments);
    }
}

package com.discordchatboxbroadcaster.event;

import com.discordchatboxbroadcaster.DiscordChatboxBroadcasterConfig;
import com.discordchatboxbroadcaster.config.XpMilestoneInterval;
import com.discordchatboxbroadcaster.notifier.Notifier;
import com.discordchatboxbroadcaster.render.ChatSegment;
import com.discordchatboxbroadcaster.render.ChatSegment.Role;
import net.runelite.api.Experience;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.events.StatChanged;

import java.awt.image.BufferedImage;
import java.util.EnumMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

public class XpMilestoneEventProcessor extends GameEventProcessor {

    private static final int LEVEL_99_XP = Experience.getXpForLevel(99);
    private static final long DEFAULT_XP_INTERVAL = 1_000_000L;

    private final DiscordChatboxBroadcasterConfig pluginConfiguration;
    private final Map<Skill, Integer> previousSkillXp = new EnumMap<>(Skill.class);

    public XpMilestoneEventProcessor(List<Notifier> registeredNotifiers, DiscordChatboxBroadcasterConfig pluginConfiguration) {
        super(registeredNotifiers);
        this.pluginConfiguration = pluginConfiguration;
    }

    @Override
    protected boolean isFeatureEnabled() {
        return pluginConfiguration.notifyXpMilestone();
    }

    @Override
    protected void processSanitizedMessage(String sanitizedMessageContent, String activePlayerName, String activeClanName, BufferedImage playerIcon, int currentTick) {
    }

    @Override
    public void evaluateGameStateChanged(GameState newGameState) {
        if (newGameState == GameState.LOGIN_SCREEN || newGameState == GameState.HOPPING) {
            previousSkillXp.clear();
        }
    }

    @Override
    public void evaluateStatChanged(StatChanged incomingStatEvent, String activePlayerName, String activeClanName, BufferedImage playerIcon, int currentTick) {
        Skill skill = incomingStatEvent.getSkill();
        if (skill == null) {
            return;
        }

        int currentXp = incomingStatEvent.getXp();
        Integer previousXp = previousSkillXp.put(skill, currentXp);
        if (previousXp == null) {
            return;
        }

        if (!isFeatureEnabled() || !canProcessEvent(currentTick)) {
            return;
        }

        if (currentXp <= previousXp || currentXp < LEVEL_99_XP) {
            return;
        }

        long intervalXp = getMilestoneIntervalXp();
        long effectivePreviousXp = Math.max((long) previousXp, (long) LEVEL_99_XP);
        long previousIntervals = effectivePreviousXp / intervalXp;
        long currentIntervals = (long) currentXp / intervalXp;

        if (currentIntervals > previousIntervals) {
            long milestoneXp = currentIntervals * intervalXp;
            String formattedXp = String.format(Locale.US, "%,d", milestoneXp);
            String skillName = skill.getName();

            List<ChatSegment> notificationSegments = buildPlayerClanPrefixSegments(activePlayerName, activeClanName, playerIcon);
            notificationSegments.add(new ChatSegment("has reached ", Role.TEXT));
            notificationSegments.add(new ChatSegment(formattedXp, Role.HIGHLIGHT));
            notificationSegments.add(new ChatSegment(" XP in ", Role.TEXT));
            notificationSegments.add(new ChatSegment(skillName, Role.HIGHLIGHT));
            notificationSegments.add(new ChatSegment("!", Role.TEXT));

            dispatchNotificationSegments(notificationSegments);
        }
    }

    private long getMilestoneIntervalXp() {
        XpMilestoneInterval interval = pluginConfiguration.xpMilestoneInterval();
        if (interval == null) {
            return DEFAULT_XP_INTERVAL;
        }
        long xp = interval.getXp();
        return xp < 1 ? DEFAULT_XP_INTERVAL : xp;
    }
}

package com.discordchatboxbroadcaster.notifier;

import com.discordchatboxbroadcaster.DiscordChatboxBroadcasterConfig;
import com.discordchatboxbroadcaster.render.ChatSegment;
import com.discordchatboxbroadcaster.render.ChatboxImageGenerator;
import com.google.gson.Gson;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.DrawManager;
import net.runelite.client.util.ImageUtil;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.MultipartBody;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;

@Slf4j
public class DiscordWebhookNotifier implements Notifier {

    private final DiscordChatboxBroadcasterConfig pluginConfiguration;
    private final OkHttpClient networkClient;
    private final ScheduledExecutorService executorService;
    private final Gson gson;
    private final DrawManager drawManager;
    private final ChatboxImageGenerator imageGenerator;
    private final BlockingQueue<PendingNotification> notificationQueue;

    private ScheduledFuture<?> scheduledWorkerTask;

    public DiscordWebhookNotifier(
            DiscordChatboxBroadcasterConfig pluginConfiguration,
            OkHttpClient networkClient,
            ScheduledExecutorService executorService,
            Gson gson,
            DrawManager drawManager) {
        this.pluginConfiguration = pluginConfiguration;
        this.networkClient = networkClient;
        this.executorService = executorService;
        this.gson = gson;
        this.drawManager = drawManager;
        this.imageGenerator = new ChatboxImageGenerator(pluginConfiguration);
        this.notificationQueue = new LinkedBlockingQueue<>();
    }

    @Override
    public void initialize() {
        scheduledWorkerTask = executorService.scheduleAtFixedRate(this::processNotificationQueue, 0, 600, TimeUnit.MILLISECONDS);
    }

    @Override
    public void terminate() {
        if (scheduledWorkerTask != null) {
            scheduledWorkerTask.cancel(false);
            scheduledWorkerTask = null;
        }
        notificationQueue.clear();
    }

    @Override
    public void dispatchNotification(List<ChatSegment> notificationSegments) {
        if (pluginConfiguration.attachScreenshot() && drawManager != null) {
            drawManager.requestNextFrameListener(image -> {
                BufferedImage screenshot = image != null ? ImageUtil.bufferedImageFromImage(image) : null;
                notificationQueue.offer(new PendingNotification(notificationSegments, screenshot));
            });
        } else {
            notificationQueue.offer(new PendingNotification(notificationSegments, null));
        }
    }

    private void processNotificationQueue() {
        try {
            PendingNotification pendingNotification = notificationQueue.poll();
            if (pendingNotification != null) {
                transmitPayload(pendingNotification);
            }
        } catch (Exception e) {
            log.debug("Error processing notification queue", e);
        }
    }

    private void transmitPayload(PendingNotification pendingNotification) {
        String targetWebhookUrl = pluginConfiguration.webhookUrl();
        if (targetWebhookUrl == null || targetWebhookUrl.trim().isEmpty()) {
            return;
        }

        byte[] generatedImageData = imageGenerator.generateChatboxImage(pendingNotification.getSegments());
        if (generatedImageData == null || generatedImageData.length == 0) {
            return;
        }

        MultipartBody.Builder requestBodyBuilder = new MultipartBody.Builder().setType(MultipartBody.FORM);

        String username = pluginConfiguration.webhookUsername();
        String avatarUrl = pluginConfiguration.webhookAvatarUrl();

        Map<String, String> payloadMap = new LinkedHashMap<>();
        if (username != null) {
            String trimmedUsername = username.trim();
            if (!trimmedUsername.isEmpty()) {
                if (trimmedUsername.length() > 80) {
                    trimmedUsername = trimmedUsername.substring(0, 80);
                }
                payloadMap.put("username", trimmedUsername);
            }
        }

        if (avatarUrl != null) {
            String trimmedAvatarUrl = avatarUrl.trim();
            if (!trimmedAvatarUrl.isEmpty()) {
                payloadMap.put("avatar_url", trimmedAvatarUrl);
            }
        }

        if (!payloadMap.isEmpty() && gson != null) {
            String payloadJson = gson.toJson(payloadMap);
            requestBodyBuilder.addFormDataPart("payload_json", payloadJson);
        }

        requestBodyBuilder.addFormDataPart(
                "files[0]",
                "notification.png",
                RequestBody.create(MediaType.parse("image/png"), generatedImageData)
        );

        if (pendingNotification.getScreenshot() != null) {
            byte[] screenshotData = convertImageToByteArray(pendingNotification.getScreenshot());
            if (screenshotData != null && screenshotData.length > 0) {
                requestBodyBuilder.addFormDataPart(
                        "files[1]",
                        "screenshot.png",
                        RequestBody.create(MediaType.parse("image/png"), screenshotData)
                );
            }
        }

        Request networkRequest = new Request.Builder()
                .url(targetWebhookUrl)
                .post(requestBodyBuilder.build())
                .build();

        networkClient.newCall(networkRequest).enqueue(new Callback() {
            @Override
            public void onFailure(Call failedCall, IOException exception) {
                log.debug("Error sending Discord webhook notification", exception);
            }

            @Override
            public void onResponse(Call successfulCall, Response networkResponse) {
                try {
                    if (!networkResponse.isSuccessful()) {
                        log.debug("Discord webhook returned non-2xx response: code={}, message={}",
                                networkResponse.code(), networkResponse.message());
                    }
                } finally {
                    networkResponse.close();
                }
            }
        });
    }

    private byte[] convertImageToByteArray(BufferedImage image) {
        if (image == null) {
            return null;
        }
        try {
            ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
            ImageIO.write(image, "png", outputStream);
            return outputStream.toByteArray();
        } catch (IOException e) {
            log.debug("Failed to encode screenshot to PNG", e);
            return null;
        }
    }
}

